#include <cmath>

extern "C" double mms_source_dens(double x, double y, double t) {
    return (-0.20000000000000001*x*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(t)*sin(x)*sin(y) - 0.5*x*sin(t)*sin(x)*cos(y) + 0.10000000000000001*x*sin(t)*sin(y)*cos(t)*pow(cos(x), 2)*cos(y) - 0.5*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*sin(x)*sin(y)*cos(t) + 0.20000000000000001*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(t)*sin(y)*cos(x) + 0.29999999999999999*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(x)*cos(t)*cos(y))/x;
}

extern "C" double mms_source_mom1(double x, double y, double t) {
    return (x*(-0.20000000000000001*pow(sin(t), 2)*sin(x)*cos(y) + 0.10000000000000001*sin(x)*cos(y) + 0.40000000000000002*cos(t))*sin(y)*cos(x) - x*(0.080000000000000016*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*pow(sin(t), 2)*sin(x)*pow(sin(y), 2)*cos(x) - 0.020000000000000004*pow(sin(t), 2)*pow(sin(y), 2)*cos(t)*pow(cos(x), 3)*cos(y) + 0.40000000000000002*sin(x)*cos(t)*cos(y)) - pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2)*(0.5*sin(x)*cos(t)*cos(y) + 2.0) + 0.20000000000000001*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(t)*cos(x)*cos(y) - 0.10000000000000001*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*sin(t)*sin(x)*pow(sin(y), 2)*cos(t)*cos(x) + (0.020000000000000004*sin(x)*cos(t)*cos(y) + 0.080000000000000016)*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2) + 0.059999999999999998*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(t)*sin(x)*sin(y)*cos(t)*cos(x)*cos(y))/x;
}

extern "C" double mms_source_mom2(double x, double y, double t) {
    return (-x*(0.29999999999999999*sin(x)*sin(y)*cos(t)*cos(y) + 0.59999999999999998*sin(y) + 0.5*cos(y))*sin(t)*sin(x) + (-0.5*pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2)*sin(x)*sin(y) + 0.59999999999999998*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(x)*cos(y) - 0.40000000000000002*sin(y)*cos(x))*cos(t) + (-0.20000000000000001*x*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(x) + 0.10000000000000001*x*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*cos(t)*pow(cos(x), 2)*cos(y) + 0.059999999999999998*x*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*sin(y)*cos(t)*pow(cos(x), 2) + 0.40000000000000002*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*cos(x))*sin(t)*sin(y))/x;
}

extern "C" double mms_source_etot(double x, double y, double t) {
    return (1.0/2.0)*(-0.20000000000000001*x*((0.5*sin(x)*cos(t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(t)*cos(x)*cos(y) + 14.999999999999998)*sin(t)*sin(x)*sin(y) - x*((0.5*sin(x)*cos(t)*cos(y) + 2.0)*(0.26000000000000001*pow(sin(x), 2)*sin(y)*cos(t) + 0.59999999999999998*sin(x) - 0.080000000000000016*sin(y)*cos(t))*sin(y) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2))*sin(x)*cos(y) + 1.2*cos(x)*cos(y))*sin(t) + 0.20000000000000001*x*((0.5*sin(x)*cos(t)*cos(y) + 2.0)*(-0.26000000000000001*pow(sin(t), 2)*sin(x)*sin(y) + 0.17999999999999999*sin(x)*sin(y) + 0.59999999999999998*cos(t))*sin(y)*cos(x) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2))*cos(t)*cos(x)*cos(y) - 2.0*sin(x)*cos(t)*cos(y))*sin(t)*sin(y)*cos(x) - (0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*(-(0.59999999999999998*(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0)*sin(x)*cos(t) + 0.080000000000000016*pow(sin(t), 2)*sin(y)*pow(cos(x), 2))*(0.5*sin(x)*cos(t)*cos(y) + 2.0)*cos(y) + 0.5*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2))*sin(x)*sin(y)*cos(t) + 2.0*sin(y)*cos(t)*cos(x)) + 0.20000000000000001*((0.5*sin(x)*cos(t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(t)*cos(x)*cos(y) + 14.999999999999998)*sin(t)*sin(y)*cos(x) + 0.29999999999999999*((0.5*sin(x)*cos(t)*cos(y) + 2.0)*(pow(0.29999999999999999*sin(x)*sin(y)*cos(t) + 1.0, 2) + 0.040000000000000008*pow(sin(t), 2)*pow(sin(y), 2)*pow(cos(x), 2)) + 2.0*cos(t)*cos(x)*cos(y) + 14.999999999999998)*sin(x)*cos(t)*cos(y))/x;
}
